#!/bin/sh
set -eu
FIXTURE_BASE64=''
emit() { printf '%s' "$FIXTURE_BASE64" | base64 -d; exit 0; }
trap emit TERM
INPUT=$(printf '%s' "${PUNCH_INPUT_BASE64:?}" | base64 -d)
WINDOW_SECONDS=$(printf '%s' "$INPUT" | sed -n 's/^{"nonce":"[0-9a-f]\{64\}","window_seconds":\([1-9][0-9]*\)}$/\1/p')
[ -n "$WINDOW_SECONDS" ] && [ "$WINDOW_SECONDS" -le 86400 ]
sleep "$WINDOW_SECONDS" & wait "$!"
emit
